  questionVariantId: string,
  choiceId: string,
  choiceLabel: string,
  timingProfileId: string,
  disposition: TestChoiceOrderDisposition,
): ExactTestChoiceOrderRecord {
  return { caseId, nodeId, questionVariantId, choiceId, choiceLabel, timingProfileId, disposition };
}

