  it("binds biopsy, MRI and specimen-review plans by exact identity and label after reordering", () => {
    expect(timings).toHaveLength(3);
    expect(orders).toHaveLength(3);
    for (const entry of timings) {
      expect(answerChoiceTimingRegistryEntrySchema.safeParse(entry).success).toBe(true);
      const node = nodes.find((node) => node.id === entry.nodeId)!;
