      }
      for (const choice of [...node.answerChoices].reverse()) {
        const binding = entry.classification.choices.find((binding) => binding.choiceId === choice.id)!;
        expect(binding.choiceLabel).toBe(choice.label);
        const expectedProfiles: Record<string, string> = {
          "tract-focus": "timing.test.biopsy",
          "rectal-ulcers": "timing.test.mri",
          "external-opening": "timing.test.pathology_review",
        };
        expect(binding.timing).toEqual({ kind: "test", timingProfileId: expectedProfiles[choice.id] });
        const order = orders.find((order) => order.questionVariantId === node.questionVariantId && order.choiceId === choice.id)!;
        expect(order.choiceLabel).toBe(choice.label);
        expect(order.disposition).toEqual({ kind: "not_executed", reason: "future_planned" });
        expect(order.requiresExecutedResult).toBe(false);
        expect(order.executedServiceId).toBeNull();
      }
    }
    for (const node of nodes) expect([node.stem, node.currentUpdate, node.explanation, ...node.answerChoices.map((choice) => choice.label)].join(" ")).not.toMatch(/\b\d+\s*(?:minutes?|hours?|days?|ticks?)\b/i);
    for (const link of packet.sourceLinkProposals) {
      expect(link.target).toBe("_blank");
      expect(link.rel).toBe("noopener noreferrer");
      expect(link.referrerPolicy).toBe("no-referrer");
    }
  });

  it("has zero raw cue findings across canonical and every finite visible context", async () => {
    const { lintQuestion } = await import(/* @vite-ignore */ new URL("tools/question-quality/lint.mjs", root).href);
    const reports: Array<{ findings: unknown[] }> = [];
    for (const clinicalCase of cases) {
      const profiles = [{ id: "canonical", presentation: clinicalCase.presentation, chiefComplaint: clinicalCase.chiefComplaint }, ...clinicalCase.approvedInstantiationProfiles!];
      for (const profile of profiles) for (const [index, node] of clinicalCase.decisionNodes.entries()) {
        const fields: Record<string, string> = {
          chiefComplaint: profile.chiefComplaint ?? clinicalCase.chiefComplaint!,
          presentation: profile.presentation,
          currentUpdate: node.currentUpdate ?? "",
          stem: node.stem,
          previousFeedback: clinicalCase.decisionNodes.slice(0, index).flatMap((prior) => [prior.explanation, ...prior.answerChoices.flatMap((choice) => [choice.label, choice.rationale ?? ""])]).join(" "),
        };
        if (node.exhibit?.kind === "keyValue") {
          fields["exhibit.caption"] = node.exhibit.caption ?? "";
          node.exhibit.items.forEach((row, rowIndex) => { fields[`exhibit.${rowIndex}`] = `${row.label}: ${row.value}`; });
        }
        reports.push(lintQuestion({
          variantId: node.questionVariantId,
          caseId: clinicalCase.id,
          profileId: profile.id,
          concept: concepts.find((concept) => concept.id === node.primaryConceptId),
          choices: node.answerChoices,
          fields,
          rationales: node.answerChoices.map((choice) => ({ choiceId: choice.id, text: choice.rationale })),
        }));
      }
    }
    expect(reports).toHaveLength(6);
    expect(reports.flatMap((report) => report.findings)).toEqual([]);
  });
});

