import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { PROTOTYPE_BALANCE_RELEASE as balance } from "@gamify-surgery/balance-config";
import { answerChoiceTimingRegistryEntrySchema, syntheticClinicalReleaseSchema } from "./schema";
import { SYNTHETIC_CLINICAL_RELEASE as live } from "./synthetic-content";
import { QUESTION_SHIP_MANIFEST as ship } from "./question-ship-manifest";
import * as old from "./question-topic-esophagus-structural-inflammatory-emergencies-20261111";

const sha = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const before = { live: sha(live), ship: sha(ship) };
const topic = await import("./question-intraop-endoscopic-perforation-and-injury-20261112");
const packet = topic.ENDOSCOPIC_INJURY_PACKET;
const ledger = topic.ENDOSCOPIC_INJURY_SOURCE_LEDGER;
const nodes = topic.ENDOSCOPIC_INJURY_NODES;
const cases = topic.ENDOSCOPIC_INJURY_CASES;
const questions = topic.ENDOSCOPIC_INJURY_QUESTIONS;
const read = (file: string) => readFileSync(new URL(`../../../${file}`, import.meta.url), "utf8");

describe("I13 endoscopic perforation and injury authoring sidecar", () => {
  it("is explicit-import only and cannot admit unsupported new live concepts", () => {
    expect({ live: sha(live), ship: sha(ship) }).toEqual(before);
    const proposed = new Set(questions.map((question) => question.id));
    expect(live.cases.flatMap((item) => item.decisionNodes).some((node) => proposed.has(node.questionVariantId))).toBe(false);
    expect(ship.accepted.some((row) => proposed.has(row.questionVariantId))).toBe(false);
    expect(topic.ENDOSCOPIC_INJURY_MANIFEST).toMatchObject({
      managerAccepted: false, independentPass: false, clinicalApproval: false,
    });
    const liveCases = cases.filter((item) => item.requiredClinicalSetting === "endoscopy");
    expect(liveCases).toHaveLength(3);
    expect(liveCases.every((item) => !item.routineEligible)).toBe(true);
    expect(packet.integrationDependencies.find((item) => item.id === "ENG-I01")!.appliesToCaseIds!.sort())
      .toEqual(liveCases.map((item) => item.id).sort());
  });

  it("audits the complete assigned live, retained and authored inventory", () => {
    const program = JSON.parse(read("docs/research/question-intraop-program-20261112.json"));
    const assigned = program.taxonomy.find((item: { slug: string }) => item.slug === topic.ENDOSCOPIC_INJURY_SLUG);
    const expected = [
      ...assigned.existingRelatedBankNodes.map((item: { recordId: string }) => item.recordId),
      ...assigned.retainedRecordIds, ...assigned.authoringDefinitionRecordIds,
    ];
    expect(packet.audit.map((item) => item.recordId).sort()).toEqual(expected.sort());
    expect(packet.counts).toMatchObject({
      auditedInventoryRows: 9, currentOccurrences: 2, retainedDefinitions: 4,
      authoredDefinitions: 3, keptRows: 9, additiveRewrites: 0, replacementProposals: 0,
      newCases: 4, newNodes: 5, newConcepts: 5, liveNodes: 4, chartReviewNodes: 1,
    });
    expect(packet.audit.every((row) => row.verdict === "Keep" && row.reason.length > 50)).toBe(true);
    for (const snapshot of packet.beforeSnapshots) {
      expect(snapshot.matchesPlanningHash, snapshot.recordId).toBe(true);
      const row = packet.assignment.assignedRecords.find((row) => row.recordId === snapshot.recordId)!;
      if ("question" in snapshot) {
        expect(sha(snapshot.question)).toBe(snapshot.questionSha256);
        expect(snapshot.questionSha256).toBe(row.questionSha256);
        const actual = [...old.ESOPHAGUS_TOPIC_CATALOG_QUESTIONS, ...old.ESOPHAGUS_TOPIC_REVIEWED_V1.questions]
          .find((question) => question.id === row.questionVariantId)!;
        expect(sha(actual)).toBe(snapshot.questionSha256);
      } else {
        expect(snapshot.contexts.length).toBeGreaterThan(0);
        for (const context of snapshot.contexts) {
          expect(sha(context.clinicalCase)).toBe(context.caseSha256);
          const node = context.clinicalCase.decisionNodes.find((node) => node.id === row.nodeId)!;
          expect(sha(node)).toBe(row.nodeSha256);
          const pool = row.recordId.startsWith("live.") ? live.cases
            : [...old.ESOPHAGUS_TOPIC_CASES, ...old.ESOPHAGUS_TOPIC_REVIEWED_V1.cases];
          expect(pool.some((item) => item.id === context.clinicalCase.id && sha(item) === context.caseSha256)).toBe(true);
        }
      }
    }
  });

  it("preserves both exact PASS/accepted versions and distinguishes clinical approval", () => {
    expect(packet.assignment.frozenReferences).toHaveLength(2);
    for (const reference of packet.assignment.frozenReferences) {
      const clinicalCase = live.cases.find((item) => item.id === reference.caseId)!;
      const node = clinicalCase.decisionNodes.find((node) => node.id === reference.nodeId)!;
      expect(sha(node)).toBe(reference.runtimeNodeSha256);
      const receipt = packet.assignment.assignedRecords.find((row) => row.recordId.startsWith("live.")
        && row.nodeId === node.id)!;
      expect(sha(clinicalCase)).toBe(receipt.caseSha256);
      for (const source of reference.sourceFiles) {
        expect(createHash("sha256").update(readFileSync(new URL(`../../../${source.path}`, import.meta.url))).digest("hex"))
          .toBe(source.sha256);
      }
      const review = JSON.parse(read(reference.independentEditorialReview.path));
      expect(review.find((item: { id: string }) => item.id === reference.questionVariantId).verdict).toBe("PASS");
      expect(reference.managerAcceptance.accepted).toBe(true);
      expect(reference.clinicalApproval).toBeNull();
      expect(reference.clinicalReviewStatus).toBe("needs_clinician_review");
    }
    expect(packet.assignment.historicalHolds.programScopedMatches).toEqual([]);
    expect(packet.assignment.historicalHolds.chronology).toContain("REVISE");
  });

  it("validates strict cases with distinct setting, tier, acuity and progression metadata", () => {
    expect(syntheticClinicalReleaseSchema.safeParse(topic.ENDOSCOPIC_INJURY_SOURCE_RELEASE).success).toBe(true);
    expect(cases).toHaveLength(4);
    expect(nodes).toHaveLength(5);
    expect(new Set(questions.map((question) => question.id)).size).toBe(5);
    expect(new Set(topic.ENDOSCOPIC_INJURY_CONCEPTS.map((concept) => concept.id)).size).toBe(5);
    for (const item of cases) {
      const context = topic.ENDOSCOPIC_INJURY_PROCEDURE_CONTEXTS.find((context) => context.caseId === item.id)!;
      expect(context.educationalTier).toBe(3);
      expect(context.facilityProgressionLevel).toBe(2);
      expect(item.earliestFacilityStage).toBe(2);
      expect("procedureContext" in item).toBe(false);
      expect("educationalTier" in item).toBe(false);
      if (item.requiredClinicalSetting === "endoscopy") {
        expect(item.requiredCapabilityIds).toEqual(["capability.endoscopy", "capability.periop_recovery"]);
        expect(context.engineeringDependency).toBe("ENG-I01");
        expect(context.allowedServiceIncomeLineIds).toEqual(["income.endoscopy"]);
        expect(["adult_colonoscopy", "adult_upper_endoscopy_with_benign_esophageal_dilation"])
          .toContain(context.procedureFamily);
      } else {
