  it("keeps all new questions, concepts, claims, presentations and profiles unapproved", () => {
    for (const record of [
      ...questions, ...topic.ENDOSCOPIC_INJURY_AUTHORING_CONCEPTS,
      ...topic.ENDOSCOPIC_INJURY_CLAIMS, ...topic.ENDOSCOPIC_INJURY_SOURCES,
      ...topic.ENDOSCOPIC_INJURY_AUTHORING_CASES, ...topic.ENDOSCOPIC_INJURY_SOURCE_LINKS,
      ...topic.ENDOSCOPIC_INJURY_STATEMENT_MAPPINGS,
