      expect(record.reviewStatus).toBe("needs_clinician_review");
      expect(record.lastClinicianReview).toBeNull();
      expect(record.aiAssistedDrafting).toBe(true);
    }
    for (const item of topic.ENDOSCOPIC_INJURY_AUTHORING_CASES) {
      expect(item.presentationReview.reviewStatus).toBe("needs_clinician_review");
      expect(item.profileReviews.every((profile) => profile.reviewStatus === "needs_clinician_review")).toBe(true);
    }
  });

  it("keeps each named adult, age/sex, finite profile and complete procedural task coherent", () => {
    for (const item of cases) {
      const authored = packet.candidateCases.find((candidate) => candidate.caseId === item.id)!;
      expect(item.patientDisplayName).toBe(authored.name);
      expect(item.prototypeDemographics).toEqual({ ageYears: authored.age, sexLabel: authored.sex });
      expect(item.prototypeDemographics!.ageYears).toBeGreaterThanOrEqual(18);
      expect(item.presentation).toContain(`${authored.age}-year-old ${authored.sex === "Female" ? "woman" : "man"}`);
      expect(item.presentation).toContain("{patientName}");
      expect(item.chiefComplaint!.split(/\s+/).length).toBeLessThanOrEqual(5);
      expect(item.approvedInstantiationProfiles).toHaveLength(1);
      expect(item.approvedInstantiationProfiles![0]!.prototypeDemographics).toEqual(item.prototypeDemographics);
      expect(item.approvedInstantiationProfiles![0]!.presentation).toBe(item.presentation);
      expect(item.pediatricProfile).toBeUndefined();
      for (const node of item.decisionNodes) {
