  it("maps every offered test by exact identity and label after option reordering", () => {
    const profiles = new Set(balance.answerChoiceTimingProfiles.map((profile) => profile.id));
    expect(topic.ENDOSCOPIC_INJURY_TIMING_ENTRIES).toHaveLength(5);
    expect(topic.ENDOSCOPIC_INJURY_ORDER_PROPOSALS).toHaveLength(1);
    for (const entry of topic.ENDOSCOPIC_INJURY_TIMING_ENTRIES) {
      expect(answerChoiceTimingRegistryEntrySchema.safeParse(entry).success).toBe(true);
      const authored = nodes.find((node) => node.nodeId === entry.nodeId)!;
      const runtime = cases.flatMap((item) => item.decisionNodes).find((node) => node.id === entry.nodeId)!;
      const reversed = [...runtime.answerChoices].reverse();
      if (entry.classification.kind === "test_choices") {
        expect(entry.classification.choices).toHaveLength(reversed.length);
        for (const binding of entry.classification.choices) {
          const choice = reversed.find((choice) => choice.id === binding.choiceId)!;
          expect(choice.label).toBe(binding.choiceLabel);
          const source = authored.choices.find((candidate) => candidate.label === choice.label)!;
          expect(binding.timing.kind === "test").toBe(source.testing);
          if (binding.timing.kind === "test") {
            expect(profiles.has(binding.timing.timingProfileId)).toBe(true);
            const proposal = topic.ENDOSCOPIC_INJURY_ORDER_PROPOSALS.find((proposal) => proposal.choiceId === choice.id)!;
            expect(proposal).toMatchObject({
              caseId: entry.caseId, nodeId: entry.nodeId, questionVariantId: entry.questionVariantId,
              choiceId: choice.id, choiceLabel: choice.label,
              serviceRequest: null, resultGateAfter: null,
              disposition: { kind: "not_executed", reason: "future_planned" },
            });
          }
        }
      } else {
        expect(entry.classification.kind).toBe("no_test");
        expect(authored.choices.every((choice) => !choice.testing)).toBe(true);
      }
    }
    const repeat = topic.ENDOSCOPIC_INJURY_ORDER_PROPOSALS[0]!;
    expect(repeat.choiceLabel).toBe("Repeat colonoscopy to reassess the clipped defect");
    expect(repeat.timing).toEqual({ kind: "test", timingProfileId: "timing.test.lower_endoscopy" });
  });

  it("has reciprocal atomic evidence mappings and safe offline source links", () => {
