    const section = (text: string, title: string) => {
      const start = text.indexOf(`### ${title}\n`);
      expect(start).toBeGreaterThan(-1);
      const boundaries = [text.indexOf("\n### ", start + 1), text.indexOf("\n## ", start + 1)]
        .filter((index) => index !== -1);
      return text.slice(start, Math.min(...boundaries, text.length));
    };
    for (const frozen of packet.reviewRound1.passFrozen) {
      const clinicalCase = cases.find((item) => item.id === frozen.caseId)!;
      const node = clinicalCase.decisionNodes.find((node) => node.id === frozen.nodeId)!;
