      const authored = nodes.find((node) => node.nodeId === frozen.nodeId)!;
      expect(sha(question)).toBe(frozen.questionSha256);
      expect(sha(node)).toBe(frozen.nodeSha256);
      expect(sha(authored)).toBe(frozen.authoredNodeSha256);
      expect(question.contentVersion).toBe(frozen.contentVersion);
      const header = Object.fromEntries(Object.entries(clinicalCase)
        .filter(([key]) => !["decisionNodes", "learningSummary"].includes(key)));
      expect(sha(header)).toBe(frozen.headerSha256);
      expect(sha(clinicalCase.decisionNodes.slice(0, clinicalCase.decisionNodes.findIndex((node) => node.id === frozen.nodeId))))
