      expect(topic.ENDOSCOPIC_INJURY_TIMING_ENTRIES.find((entry) => entry.nodeId === node.id))
        .toEqual(packet.reviewRound1.reviewedBundle.timingEntries.find((entry) => entry.nodeId === node.id));
      expect(section(markdown, authored.title)).toBe(section(packet.reviewRound1.reviewedMarkdown, authored.title));
