    expect(round.summary).toMatchObject({ reviewed: 5, PASS: 3, REVISE: 2, FAIL: 0, preserved: 3, revisionAttempts: 2, noteResponses: 49, returnedNoteResponses: 23 });
    for (const item of round.items) {
      const reviewed = round.independentReview.find((review) => review.id === item.questionVariantId)!;
      expect(item.attemptCount).toBe(reviewed.verdict === "PASS" ? 0 : 1);
      for (const field of noteFields) {
        const responses = item.issueResponses.filter((response) => response.field === field);
        expect(responses.map((response) => response.originalFinding)).toEqual(reviewed[field]);
        expect(responses.map((response) => response.index)).toEqual(reviewed[field].map((_, index) => index));
        expect(responses.every((response) => response.response.length > 60)).toBe(true);
      }
      expect(item.issueResponses.length).toBe(noteFields.reduce((sum, field) => sum + reviewed[field].length, 0));
