    expect(ledger.revisionRound1).toMatchObject({ newRetrievals: 0 });
    expect(ledger.revisionRound1.addedClaimIds).toEqual(["claim.intraop.endoscopic-perforation-and-injury.closure-contamination-distinction"]);
  });

  it("has zero unsuppressed raw cue findings in every full visible profile/sequence", async () => {
    const linterPath = new URL("../../../tools/question-quality/lint.mjs", import.meta.url).href;
    const { lintQuestion } = await import(/* @vite-ignore */ linterPath);
    const reports = [];
    for (const item of cases) for (const [index, node] of item.decisionNodes.entries()) {
      for (const profile of [null, ...item.approvedInstantiationProfiles!]) {
        const context = profile ?? item;
        const display = (text: string) => profile ? text.replaceAll("{patientName}", item.patientDisplayName) : text;
        reports.push(lintQuestion({
          variantId: node.questionVariantId, caseId: item.id, profileId: profile?.id ?? null,
          concept: topic.ENDOSCOPIC_INJURY_CONCEPTS.find((concept) => concept.id === node.primaryConceptId),
          choices: node.answerChoices,
          rationales: node.answerChoices.map((choice) => ({ choiceId: choice.id, text: choice.rationale })),
          fields: {
            chiefComplaint: display(context.chiefComplaint ?? ""), presentation: display(context.presentation),
            currentUpdate: display(node.currentUpdate ?? ""), stem: display(node.stem),
            priorFeedback: display(item.decisionNodes.slice(0, index).map((previous) => [
              previous.stem, previous.currentUpdate, ...previous.answerChoices.map((choice) => choice.label),
              previous.explanation, ...previous.answerChoices.map((choice) => choice.rationale),
            ].join(" ")).join(" ")),
