});

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { answerChoiceTimingRegistryEntrySchema, validateSyntheticClinicalRelease } from "./schema";
import * as authored from "./question-intraop-ercp-access-and-adverse-events-20261112";

const root = new URL("../../../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");
const sha = (value: unknown) => createHash("sha256")
  .update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
interface Before {
  recordId: string; inventoryKind: string; caseId?: string; nodeId?: string; questionVariantId: string; conceptId: string;
  nodeSha256?: string; questionSha256?: string; caseSha256?: string; exactDefinition: unknown; currentDefinitionMatch: boolean;
  acceptance?: unknown; source: { file: string; export: string };
  allSourceContexts: Array<{ header: unknown; headerSha256: string; precedingNodes: unknown[];
    precedingNodesSha256: string; origins: Array<{ file: string; export: string }> }>;
}
interface LintReport { findings: unknown[]; metrics: { completeAuthoredRationales: boolean } }
const packet = JSON.parse(read("docs/research/question-intraop-ercp-access-and-adverse-events-20261112.json")) as {
  assignment: { id: string; slug: string; setting: { primary: string; runtimeSetting: string }; retainedRecordIds: string[];
    authoringDefinitionRecordIds: string[]; existingRelatedBankNodes: Array<{ recordId: string }> };
  before: Before[];
  audit: Array<{ recordId: string; verdict: string | null; planningDisposition: string | null; beforeSha256: string }>;
  counts: { inventoryRecords: number; kept: number; heldPlanningRecords: number; newDecisions: number; newCases: number };
  freeze: { currentLive: Before[]; clinicalApprovals: Array<{ reviewer: string; questions: Array<{ questionVariantId: string;
    questionSha256: string; contentVersion: string }> }>; sourceFreezeReceipts: unknown[] };
  exportsSnapshot: Record<string, unknown>;
  proposedItems: Array<{ nodeId: string; questionVariantId: string; exactAfterSha256: string; exactQuestionSha256: string }>;
  cueLint: { contexts: number; variantCount: number; version: string; findings: unknown[]; suppressions: unknown[]; reports: LintReport[] };
  withheldTeachingPoints: Array<{ id: string; claimIds: string[]; reason: string }>;
  revisionRound: number;
  revisionRound1: {
    round: number;
    reviewInput: { path: string; sha256: string; records: Array<{ id: string; nodeId: string; verdict: string;
      clarityIssues: string[]; cues: Array<{ phrase: string; why: string }>; fairness: string[]; suggestions: string[] }> };
    reviewedSnapshot: { I18_QUESTIONS: typeof authored.I18_QUESTIONS; I18_CASES: typeof authored.I18_CASES;
      I18_ITEMS: typeof authored.I18_ITEMS; I18_CONCEPTS: typeof authored.I18_CONCEPTS;
      I18_AUTHORING_CONCEPTS: typeof authored.I18_AUTHORING_CONCEPTS; I18_AUTHOR_CHECKS: typeof authored.I18_AUTHOR_CHECKS;
      I18_STATEMENT_MAPPINGS: typeof authored.I18_STATEMENT_MAPPINGS; I18_CLAIMS: typeof authored.I18_CLAIMS;
      I18_SOURCES: typeof authored.I18_SOURCES };
    passFrozen: Array<{ questionVariantId: string; nodeId: string; caseId: string; contentVersion: string;
      questionSha256: string; nodeSha256: string; wholeCaseSha256: string; caseHeaderSha256: string;
      precedingNodesSha256: string; conceptSha256: string; itemSha256: string }>;
    frozenPassMarkdown: { section: string; sha256: string };
    attempts: Array<{ questionVariantId: string; nodeId: string; attemptCount: number;
      beforeQuestionSha256: string; afterQuestionSha256: string; beforeNodeSha256: string; afterNodeSha256: string;
      beforeVersion: string; afterVersion: string; disposition: string }>;
    noteResponses: Array<{ questionVariantId: string; category: string; index: number; note: unknown; response: string; status: string }>;
  };
};
const ledger = JSON.parse(read("docs/research/sources-question-intraop-ercp-access-and-adverse-events-20261112.json")) as {
  sources: typeof authored.I18_SOURCES; evidenceClaims: typeof authored.I18_CLAIMS;
  statementMappings: typeof authored.I18_STATEMENT_MAPPINGS;
  sourceUseRules: { fullTextStored: boolean; sourceExcerptsStored: boolean; gameplayNetwork: boolean };
  excludedSourceRecords: Array<{ id: string; evidenceClaimIds: string[]; reason: string }>;
};
function objects(value: unknown, seen = new Set<object>(), out: Record<string, unknown>[] = []) {
  if (!value || typeof value !== "object" || seen.has(value)) return out;
  seen.add(value);
  if (!Array.isArray(value)) out.push(value as Record<string, unknown>);
  for (const child of Object.values(value)) if (child && typeof child === "object") objects(child, seen, out);
  return out;
}

describe("I18 ERCP explicit-import authoring sidecar", () => {
  it("accounts for all assigned exact records without treating held planning drafts as scored verdicts", () => {
    expect(packet.assignment).toMatchObject({ id: "I18", slug: "ercp-access-and-adverse-events",
      setting: { primary: "chart_review", runtimeSetting: "clinic" } });
    expect(packet.before).toHaveLength(38);
    expect(new Set(packet.before.map(row => row.recordId)).size).toBe(38);
    expect(packet.before.filter(r => r.inventoryKind === "liveCoverage").map(r => r.recordId))
      .toEqual(packet.assignment.existingRelatedBankNodes.map(r => r.recordId));
    expect(packet.before.filter(r => r.inventoryKind === "retainedCoverage").map(r => r.recordId)).toEqual(packet.assignment.retainedRecordIds);
    expect(packet.before.filter(r => r.inventoryKind === "authoringDefinitions").map(r => r.recordId)).toEqual(packet.assignment.authoringDefinitionRecordIds);
    expect(packet.audit).toHaveLength(38);
    expect(packet.audit.filter(row => row.verdict === "Keep")).toHaveLength(32);
    expect(packet.audit.filter(row => row.verdict === null && row.planningDisposition)).toHaveLength(6);
    expect(packet.counts).toMatchObject({ inventoryRecords: 38, kept: 32, heldPlanningRecords: 6, newDecisions: 4, newCases: 2 });
  });

  it("rechecks real exported definitions and every retained header/preceding-node context", async () => {
    const modules = new Map<string, Record<string, unknown>>();
    const exported = new Map<string, Record<string, unknown>[]>();
    const getObjects = async (file: string, name: string) => {
      if (!modules.has(file)) modules.set(file, await import(new URL(file, root).href) as Record<string, unknown>);
      const key = `${file}:${name}`;
      if (!exported.has(key)) exported.set(key, objects(modules.get(file)![name]));
      return exported.get(key)!;
    };
    let contexts = 0;
    for (const row of packet.before) {
      const expected = row.nodeSha256 ?? row.questionSha256;
      expect(row.currentDefinitionMatch, row.recordId).toBe(true);
      expect(sha(row.exactDefinition), row.recordId).toBe(expected);
      expect((await getObjects(row.source.file, row.source.export)).some(value =>
        value.id === (row.nodeId ?? row.questionVariantId) && sha(value) === expected), row.recordId).toBe(true);
      expect(packet.audit.find(r => r.recordId === row.recordId)?.beforeSha256).toBe(expected);
      for (const context of row.allSourceContexts) {
        contexts += 1;
        expect(sha(context.header)).toBe(context.headerSha256);
        expect(sha(context.precedingNodes)).toBe(context.precedingNodesSha256);
        for (const origin of context.origins) {
          expect((await getObjects(origin.file, origin.export)).filter(c => Array.isArray(c.decisionNodes)).some(c => {
            const { decisionNodes, ...header } = c;
            const nodes = decisionNodes as Array<{ id: string }>;
            const i = nodes.findIndex(n => n.id === row.nodeId && sha(n) === row.nodeSha256);
            return i >= 0 && sha(header) === context.headerSha256 && sha(nodes.slice(0, i)) === context.precedingNodesSha256;
          }), `${row.recordId}: ${origin.file}:${origin.export}`).toBe(true);
        }
      }
    }
    expect(contexts).toBe(29);
  }, 30_000);

  it("freezes accepted current versions and both named clinical approvals without promoting new material", () => {
