    expect(packet.freeze.clinicalApprovals[0]!.reviewer).toBe("Melissa Rowland, MD");
    expect(packet.freeze.clinicalApprovals[0]!.questions).toHaveLength(2);
    for (const q of packet.freeze.clinicalApprovals[0]!.questions) {
      const old = packet.before.find(r => r.inventoryKind === "authoringDefinitions" && r.questionVariantId === q.questionVariantId)!;
