const root = new URL("../../../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");
const sha = (value: unknown) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
interface SavedContext {
  header: Record<string, unknown>; headerSha256: string; precedingNodes: unknown[];
  origins: Array<{ file: string; export: string }>;
}
interface Before {
  recordId: string; inventoryKind: string; nodeId?: string; questionVariantId: string; conceptId: string;
  nodeSha256?: string; questionSha256?: string; currentDefinitionMatch: boolean;
  exactDefinition: unknown; source: { file: string; export: string }; allSourceContexts: SavedContext[];
}
interface LintReport { variantId: string; caseId: string; profileId: string | null; findings: unknown[] }
const packet = JSON.parse(read("docs/research/question-intraop-pediatric-endoscopy-foreign-body-20261112.json")) as {
  assignment: { id: string; slug: string; exactInventoryRecordIds: Record<string, string[]>; ownedFiles: string[] };
  before: Before[];
  audit: Array<{ recordId: string; verdict: string | null; planningDisposition: string | null; beforeSha256: string; reason: string }>;
  freeze: { clinicalApprovals: unknown[]; editorialPass: Array<{ path: string; decision: { verdict: string } }>;
    liveAccepted: Array<{ recordId: string; nodeSha256: string }>;
    sourceReceipts: Array<{ sourcePath: string; sourceNodeSha256: string; sourceQuestionSha256: string; questionVariantId: string }>;
    editorialPassOriginalCases: Array<{ clinicalCase: unknown; sha256: string; source: { file: string; export: string } }> };
  reviewReferences: Array<{ path: string; sha256: string }>;
  proposedItems: Array<{ nodeId: string; questionVariantId: string; exactAfterSha256: string; exactQuestionSha256: string }>;
  exportsSnapshot: Record<string, unknown>;
  cueLint: { version: string; contexts: number; variantCount: number; findings: unknown[]; suppressions: unknown[]; reports: LintReport[] };
  ownerApprovalsNeeded: Array<{ kind: string; owner: string }>;
