import { ROW_046_CLINICAL_APPROVAL, ROW_046_CONCEPTS, ROW_046_QUESTION_VARIANTS } from "./approved-data/meckel-resection-extent";
import { QUESTION_SHIP_MANIFEST } from "./question-ship-manifest";
import { SYNTHETIC_CLINICAL_RELEASE } from "./synthetic-content";

const sha = (v: unknown) => createHash("sha256").update(JSON.stringify(v)).digest("hex");
const id = topic.unexpectedBowelId;
const cases = topic.UNEXPECTED_BOWEL_CASES;
const questions = topic.UNEXPECTED_BOWEL_QUESTIONS;
interface AuditRow {
  recordId: string; caseId?: string; nodeId?: string; questionVariantId: string; conceptId: string;
  beforeVersion: string; beforeSha256: string; observedSha256: string; beforeDefinition: unknown;
  source: { file: string; export: string }; verdict: string; supplyDisposition: string;
  reviewReferences: Array<{ path: string; verdict: string }>; limitations: string[]; changedByWorker: boolean;
  retainedContexts: Array<{ caseId: string; caseSha256: string; header: Record<string, unknown>; visiblePrecedingNodes: unknown[] }>;
}
const audit = packet.audit as unknown as AuditRow[];
function objects(root: unknown): Record<string, unknown>[] {
  const seen = new Set<object>(); const out: Record<string, unknown>[] = [];
  function visit(v: unknown) {
    if (!v || typeof v !== "object" || seen.has(v)) return;
    seen.add(v); const obj = v as Record<string, unknown>; out.push(obj); Object.values(obj).forEach(visit);
  }
  visit(root); return out;
}

describe("I02 unexpected appendix and bowel findings explicit authoring sidecar", () => {
  it("audits every assigned exact occurrence, retained node and authored definition", () => {
    const assignment = program.taxonomy.find(t => t.slug === "unexpected-appendix-and-bowel-findings")!;
    expect(packet.assignment).toEqual(assignment);
    const assigned = [...assignment.existingRelatedBankNodes.map(r => r.recordId), ...assignment.retainedRecordIds, ...assignment.authoringDefinitionRecordIds];
    expect(audit.map(r => r.recordId).sort()).toEqual(assigned.sort());
    expect(new Set(assigned).size).toBe(27);
    expect(packet.inventoryTotals).toMatchObject({ currentOccurrences: 4, retainedNodeDefinitions: 9, authoredQuestionDefinitions: 14, keep: 27, additiveRewrites: 0, retireAndReplace: 0, newDecisions: 3, newCases: 3 });
    for (const row of audit) {
      expect(row.verdict).toBe("Keep"); expect(row.changedByWorker).toBe(false);
      expect(sha(row.beforeDefinition)).toBe(row.beforeSha256); expect(row.observedSha256).toBe(row.beforeSha256);
      expect(row.beforeVersion).toBeTruthy(); expect(row.reviewReferences.length).toBeGreaterThan(0); expect(row.limitations.length).toBeGreaterThan(0);
    }
  });

  it("re-resolves original source exports and their exact retained case/header/profile contexts", async () => {
    const modules = new Map<string, Record<string, unknown>>();
    for (const row of audit) {
      if (!modules.has(row.source.file)) {
        const url = new URL(`../../../${row.source.file}`, import.meta.url).href;
        modules.set(row.source.file, await import(/* @vite-ignore */ url));
      }
      const values = objects(modules.get(row.source.file)![row.source.export]);
      const identity = row.nodeId ?? row.questionVariantId;
      expect(values.some(v => v.id === identity && sha(v) === row.beforeSha256), row.recordId).toBe(true);
      for (const context of row.retainedContexts) {
        const current = values.find(v => v.id === context.caseId && Array.isArray(v.decisionNodes) && sha(v) === context.caseSha256)!;
        expect(current, `${row.recordId}/${context.caseId}`).toBeTruthy();
        expect(Object.fromEntries(Object.keys(context.header).map(key => [key, current[key]]))).toEqual(context.header);
      }
    }
    expect(audit.reduce((sum, r) => sum + r.retainedContexts.length, 0)).toBe(13);
  }, 30_000);

  it("preserves four accepted pathology versions and all four named historical Meckel approvals", () => {
    expect(packet.frozenItems).toHaveLength(4); expect(packet.clinicalApprovalQuestionFreezes).toHaveLength(4);
