    expect(ROW_046_CLINICAL_APPROVAL.reviewer).toBe("Melissa Rowland, MD");
    expect(ROW_046_CLINICAL_APPROVAL.deferredElements).toContain("incidental_asymptomatic_meckel_management");
    for (const freeze of packet.clinicalApprovalQuestionFreezes) {
