    expect(audit.filter(r => r.recordId.startsWith("retained.") && r.conceptId.includes("meckel")).every(r => r.supplyDisposition === "preserve_archival_only_not_new_acceptance")).toBe(true);
    const meckelDefinitions = packet.relatedConceptAudit.filter(r => r.definition.id === ROW_046_CONCEPTS[0]!.id);
    expect(meckelDefinitions).toHaveLength(2);
    const raw = meckelDefinitions.find(r => r.source.endsWith("#ROW_046_CONCEPTS"))!;
    const normalized = meckelDefinitions.find(r => r.source.endsWith("#SYNTHETIC_CLINICAL_RELEASE.concepts"))!;
    expect(raw.definition).toEqual(ROW_046_CONCEPTS[0]); expect(raw.sha256).toBe(sha(ROW_046_CONCEPTS[0]));
    expect(normalized.sha256).toBe(sha(SYNTHETIC_CLINICAL_RELEASE.concepts.find(c => c.id === raw.definition.id)));
    expect(packet.supplementarySiblingAudit).toHaveLength(2);
    for (const sibling of packet.supplementarySiblingAudit) {
      const c = SYNTHETIC_CLINICAL_RELEASE.cases.find(c => c.id === sibling.caseId)!;
